details.patch:
--- sum.js
+++ sum.js
@@ -1,3 +1,3 @@
 export function sum(a, b) {
-  return a - b;
+  return a + b;
 }

arguments.command:
cat >> sum.test.js <<'EOF'
test('adds zero operands', () => {
  assert.equal(sum(0, 0), 0);
  assert.equal(sum(0, 7), 7);
  assert.equal(sum(7, 0), 7);
});
test('adds negative operands', () => {
  assert.equal(sum(-2, -3), -5);
  assert.equal(sum(-2, 5), 3);
  assert.equal(sum(2, -5), -3);
});
EOF
node --test 2>&1 | grep -E "^(✔|✖|ℹ (tests|pass|fail))"

